package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"time"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Category string `json:"category"`
	Price    float64 `json:"price"`
}

type AuditEntry struct {
	Timestamp time.Time `json:"ts"`
	Action    string    `json:"action"`
	IP        string    `json:"ip"`
}

func initDB() {
	connStr := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
}

func auditLog(r *http.Request, action string) {
	entry := AuditEntry{
		Timestamp: time.Now(),
		Action:    action,
		IP:        r.RemoteAddr,
	}
	data, _ := json.Marshal(entry)
	// Audit to structured log - safe
	log.Printf("AUDIT: %s", string(data))
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	category := r.URL.Query().Get("cat")
	sortField := r.URL.Query().Get("sort")
	order := r.URL.Query().Get("order")

	// Validate category - parameterized
	if category == "" {
		category = "all"
	}

	// Sort field validation - allowlist
	allowedSorts := map[string]bool{"name": true, "price": true, "id": true, "category": true}
	if !allowedSorts[sortField] {
		sortField = "id"
	}

	// Order validation - looks safe but has a subtle bypass
	order = strings.ToUpper(strings.TrimSpace(order))
	if order != "ASC" && order != "DESC" {
		order = "ASC"
	}

	// The vulnerability: category is used in a LIKE clause via fmt.Sprintf
	// The developer assumed the parameterized-looking code below was safe
	// but actually builds the WHERE clause dynamically
	var query string
	if category == "all" {
		query = fmt.Sprintf("SELECT id, name, category, price FROM products ORDER BY %s %s LIMIT 50", sortField, order)
	} else {
		// VULNERABLE: category is injected directly into the query
		query = fmt.Sprintf("SELECT id, name, category, price FROM products WHERE category = '%s' ORDER BY %s %s LIMIT 50", category, sortField, order)
	}

	auditLog(r, fmt.Sprintf("search:cat=%s", category))

	rows, err := db.Query(query)
	if err != nil {
		// Intentionally vague error to not leak schema
		http.Error(w, "Search temporarily unavailable", 503)
		log.Printf("DB error: %v", err)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Name, &sr.Category, &sr.Price); err != nil {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	initDB()
	http.HandleFunc("/api/v2/products/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Printf("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
